import struct, zlib
from pathlib import Path

def read_array(data, i, code):
    length, enc, clen = struct.unpack_from('<III', data, i)
    i += 12
    raw = data[i:i+clen]
    i += clen
    if enc == 1:
        raw = zlib.decompress(raw)
    return raw, length, i

def read_prop(data, i):
    t = chr(data[i]); i += 1
    if t == 'Y':
        return struct.unpack_from('<h', data, i)[0], i+2
    if t == 'C':
        return data[i], i+1
    if t == 'I':
        return struct.unpack_from('<i', data, i)[0], i+4
    if t == 'F':
        return struct.unpack_from('<f', data, i)[0], i+4
    if t == 'D':
        return struct.unpack_from('<d', data, i)[0], i+8
    if t == 'L':
        return struct.unpack_from('<q', data, i)[0], i+8
    if t in 'SR':
        n = struct.unpack_from('<I', data, i)[0]; i += 4
        return data[i:i+n].decode('utf-8','replace'), i+n
    if t in 'fdlib':
        raw, length, i = read_array(data, i, t)
        return (t, length, raw), i
    raise ValueError(t)

def walk(data, start, end, out):
    i = start
    while i + 13 <= end:
        end_off, num_props, prop_len = struct.unpack_from('<III', data, i)
        name_len = data[i+12]
        if end_off == 0 or end_off > len(data) or name_len > 200:
            break
        name = data[i+13:i+13+name_len].decode('ascii','replace')
        j = i+13+name_len
        props = []
        for _ in range(num_props):
            val, j = read_prop(data, j)
            props.append(val)
        if name in ('PolygonVertexIndex','Model','Geometry'):
            out.append((name, props[:2]))
        if j < end_off:
            walk(data, j, end_off, out)
        i = end_off

def tris_from_indices(raw, length):
    vals = struct.unpack_from('<%di' % length, raw)
    # negative marks last index of a polygon
    polys = 0
    tris = 0
    n = 0
    for v in vals:
        n += 1
        if v < 0:
            if n >= 3:
                tris += n - 2
            polys += 1
            n = 0
    return tris, polys

for path in [
    r'Assets/EnvironmentAssets/ANGRY MESH/Stylized Pack - Meadow Environment/Sources/Meshes/Grass/SM_Grass_01_02.fbx',
    r'Assets/EnvironmentAssets/ANGRY MESH/Stylized Pack - Meadow Environment/Sources/Meshes/Trees/SM_BirchTree_01.fbx',
    r'Assets/EnvironmentAssets/ANGRY MESH/Stylized Pack - Meadow Environment/Sources/Meshes/Trees/SM_OakTree_01.fbx',
]:
    data = Path(path).read_bytes()
    out = []
    walk(data, 27, len(data), out)
    print('==', Path(path).name)
    # models
    for name, props in out:
        if name == 'Model' and props:
            print(' model', props[0] if isinstance(props[0], str) else props[1] if len(props)>1 else props)
    idx = 0
    for name, props in out:
        if name == 'PolygonVertexIndex' and props and isinstance(props[0], tuple):
            code, length, raw = props[0]
            tris, polys = tris_from_indices(raw, length)
            print(f'  mesh{idx}: indices {length} polys {polys} tris {tris}')
            idx += 1
"
